<?php
 namespace Pterodactyl\Services\Dezerx; class Locales { public const REFERENCE = 'en'; private const DIRECTORY = 'resources/scripts/i18n/locales'; private static ?array $codes = null; public static function codes(): array { if (self::$codes !== null) { return self::$codes; } $found = []; foreach (glob(base_path(self::DIRECTORY) . '/*.json') ?: [] as $path) { $code = basename($path, '.json'); if ($code !== '') { $found[] = $code; } } sort($found); if (in_array(self::REFERENCE, $found, true)) { $found = [self::REFERENCE, ...array_values(array_diff($found, [self::REFERENCE]))]; } return self::$codes = $found === [] ? [self::REFERENCE] : $found; } public static function has(string $code): bool { return in_array($code, self::codes(), true); } } 